import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.StringTokenizer;

public class Main {

    static ArrayList<Integer> solveOne(int n, String s) {
        ArrayList<Integer> stack = new ArrayList<>();      // 存未匹配的 'U' 下标
        ArrayList<Integer> badDown = new ArrayList<>();    // 存未匹配的 'D' 下标

        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            int idx = i + 1; // 下标从1开始

            if (ch == 'U') {
                stack.add(idx);
            } else { // ch == 'D'
                if (!stack.isEmpty()) {
                    stack.remove(stack.size() - 1); // 匹配掉一对 U...D
                } else {
                    badDown.add(idx);
                }
            }
        }

        ArrayList<Integer> ans = new ArrayList<>();
        int a = badDown.size();
        int b = stack.size();

        // 翻转最前面的 ceil(a/2) 个未匹配 D
        int needDown = (a + 1) / 2;
        for (int i = 0; i < needDown; i++) {
            ans.add(badDown.get(i));
        }

        // 翻转最后面的 ceil(b/2) 个未匹配 U
        int needUp = (b + 1) / 2;
        for (int i = b - needUp; i < b; i++) {
            ans.add(stack.get(i));
        }

        return ans;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        StringTokenizer st;

        int T = Integer.parseInt(br.readLine().trim());
        while (T-- > 0) {
            int n = Integer.parseInt(br.readLine().trim());
            String s = br.readLine().trim();

            ArrayList<Integer> ans = solveOne(n, s);
            sb.append(ans.size()).append('\n');
            if (ans.isEmpty()) {
                sb.append('\n');
            } else {
                for (int i = 0; i < ans.size(); i++) {
                    if (i > 0) sb.append(' ');
                    sb.append(ans.get(i));
                }
                sb.append('\n');
            }
        }

        System.out.print(sb.toString());
    }
}
